S = SETUP_STD
# 46
A('46', 'listing-lead-matcher', 'Real-estate listing to buyer matcher', 'Local business', 'When a new listing is added (webhook or MLS feed), matches it against your buyer sheet by price, beds and area and emails each matching buyer a short note you can personalise.',
 ('webhook', 'new-listing'), [cfg(), norm("return [{json:{address:b.address,price:Number(b.price),beds:Number(b.beds),area:String(b.area||'').toLowerCase(),link:b.link||''}}];"), sheet_read('Read buyers'),
  code('Match buyers', "const L=$('Normalize').first().json;const out=$input.all().map(i=>i.json).filter(r=>r.email&&Number(r.max_price)>=L.price&&Number(r.min_beds||0)<=L.beds&&(!r.areas||String(r.areas).toLowerCase().split(',').map(s=>s.trim()).includes(L.area))).map(r=>({json:{name:r.name,email:r.email,address:L.address,price:L.price,beds:L.beds,link:L.link}}));return out.length?out:[{json:{none:true}}];"),
  iff('!$json.none', [mail('Email matching buyer', '$json.email', "'New listing that fits: ' + $json.address", "'Hi ' + $json.name + ', a new ' + $json.beds + ' bed at ' + $json.address + ' is listed at $' + $json.price.toLocaleString('en-US') + '. Details: ' + $json.link + '. Want a showing this week?'")])],
 {'address': '12 Maple St', 'price': 450000, 'beds': 3, 'area': 'Westside', 'link': 'https://mls.example/12'}, ['Sheet columns: name, email, max_price, min_beds, areas (comma separated).'] + S[1:], {'Read buyers': [{'name': 'Dee', 'email': 'd@x.com', 'max_price': '500000', 'min_beds': '3', 'areas': 'westside, lakeview'}, {'name': 'Ed', 'email': 'e@x.com', 'max_price': '300000', 'min_beds': '2', 'areas': 'westside'}]}, ['Email matching buyer'])
