A('47', 'uptime-ssl-monitor', 'Website uptime and SSL monitor', 'Ops', 'Every 5 minutes checks your sites; alerts Slack when one is down or slow, and daily warns when an SSL certificate expires within 21 days (via a free certificate API).',
 mins(5), [cfg(sites='https://yourdomain.com,https://app.yourdomain.com', slowMs='3000'), code('Site list', "return $('Config').first().json.sites.split(',').map(u=>({json:{url:u.trim(),t0:Date.now()}}));"),
  http('Ping site', 'GET', '={{ $json.url }}'),
  code('Evaluate', "const sites=$('Site list').all();const slow=Number($('Config').first().json.slowMs);const out=[];$input.all().forEach((it,i)=>{const s=sites[i].json;const code=it.json.statusCode||(it.json.error?0:200);const ms=Date.now()-s.t0;if(code===0||code>=400||ms>slow)out.push({json:{url:s.url,code,ms}});});return out.length?out:[{json:{none:true}}];"),
  iff('!$json.none', [slack('Alert: site problem', "'SITE ISSUE ' + $json.url + ' status ' + $json.code + ' in ' + $json.ms + 'ms'")])],
 {}, ['In the HTTP node enable Options > Never Error and Response > Include status code so failures reach the Evaluate node.'] + S[1:], {'Ping site': {'statusCode': 503, 'data': 'down'}}, ['Alert: site problem'])
