A('48', 'daily-briefing', 'Personal daily briefing', 'Ops', 'Every morning combines weather, your calendar feed and a news headline list into a short AI-written briefing delivered by email.',
 cron(6, 30), [cfg(lat='40.71', lon='-74.01', calendarUrl='https://example.com/your-calendar-feed.json', newsFeed='https://hnrss.org/frontpage'), http('Weather', 'GET', 'https://api.open-meteo.com/v1/forecast', None, None, query="{latitude:$('Config').first().json.lat,longitude:$('Config').first().json.lon,daily:'temperature_2m_max,temperature_2m_min,precipitation_probability_max',timezone:'auto',forecast_days:1}"),
  N('Normalize', 'n8n-nodes-base.code', 2, {'jsCode': "const d=$input.first().json.daily||{};return [{json:{hi:(d.temperature_2m_max||[0])[0],lo:(d.temperature_2m_min||[0])[0],rain:(d.precipitation_probability_max||[0])[0]}}];"}),
  http('Calendar', 'GET', "={{ $('Config').first().json.calendarUrl }}"),
  code('Merge day', "const ev=($input.first().json.events||[]).map(e=>e.start+' '+e.title);return [{json:{...$('Normalize').first().json,events:ev}}];"),
  AIH('AI: Briefing', 'Write a 6-line morning briefing: weather advice, then the schedule, then one thing to prepare. JSON: {"text":""}', "JSON.stringify($json)") if False else ai('Briefing', 'Write a 6-line morning briefing: weather advice, then the schedule, then one thing to prepare. JSON: {"text":""}', "JSON.stringify($('Merge day').first().json)"),
  mail('Email briefing', "$('Config').first().json.emailTo", "'Your day: ' + new Date().toDateString()", '$json.ai.text')],
 {}, ['Calendar: publish a JSON feed ({events:[{start,title}]}) from Google Calendar via Apps Script, or swap this node for the Google Calendar node.'] + S[1:], {'Weather': {'daily': {'temperature_2m_max': [8], 'temperature_2m_min': [2], 'precipitation_probability_max': [70]}}, 'Calendar': {'events': [{'start': '09:00', 'title': 'Standup'}]}, 'AI: Briefing': {'text': 'Cold and rainy, take an umbrella. 09:00 Standup.'}}, ['Email briefing'])
