A('49', 'digital-product-fulfilment', 'Digital product sale fulfilment', 'Ecommerce', 'On a Gumroad, Lemon Squeezy or Stripe sale it generates the licence key, emails the buyer the download and key, logs the sale and posts to Slack. Ideal for selling software or templates.',
 ('webhook', 'sale'), [cfg(downloadUrl='https://yourdomain.com/download/product.zip', productName='Your Product'), norm("const a=(b.data&&b.data.attributes)||{};return [{json:{email:b.email||a.user_email||(b.data&&b.data.object&&b.data.object.customer_details&&b.data.object.customer_details.email),name:b.full_name||a.user_name||'there',amount:Number(b.price||a.total||0)/100,order:String(b.sale_id||(b.data&&b.data.id)||Date.now())}}];"),
  code('Make licence key', "const j=$input.first().json;const abc='ABCDEFGHJKLMNPQRSTUVWXYZ23456789';let h=0;for(const ch of j.order+j.email)h=(h*131+ch.charCodeAt(0))>>>0;const seg=()=>{let s='';for(let i=0;i<5;i++){h=(h*1103515245+12345)>>>0;s+=abc[h%abc.length];}return s;};return [{json:{...j,key:seg()+'-'+seg()+'-'+seg()+'-'+seg()}}];"),
  mail('Email key and download', '$json.email', "'Your ' + $('Config').first().json.productName + ' download'", "'Hi ' + $json.name + ',\\n\\nThanks for your purchase!\\nDownload: ' + $('Config').first().json.downloadUrl + '\\nLicence key: ' + $json.key + '\\n\\nReply to this email if you need help.'"),
  row('Row: sale', "return [{json:{date:new Date().toISOString(),order:j.order,email:j.email,amount:j.amount,key:j.key}}];"), sheet_append('Log sale'),
  slack('Alert: sale', "'Sale ' + $('Make licence key').first().json.amount.toFixed(2) + ' from ' + $('Make licence key').first().json.email")],
 {'email': 'buyer@x.com', 'full_name': 'Buyer One', 'price': 2900, 'sale_id': 'S-1001'}, ['Replace the key generator with your own licence server call if you have one.'] + S, {}, ['Email key and download', 'Log sale', 'Alert: sale'])
