A('50', 'webinar-followup', 'Webinar and event registration follow-up', 'Marketing', 'Registrant gets a confirmation and calendar reminder; after the event attendees get the replay and a time-limited offer, no-shows get the replay only.',
 ('webhook', 'event-attendance'), [cfg(replayUrl='https://yourdomain.com/replay', offerUrl='https://yourdomain.com/offer', offerHours='48'), norm("return [{json:{name:b.name||'there',email:b.email,attended:b.attended===true||String(b.attended)==='true',event:b.event||'our webinar'}}];"),
  iff('$json.attended', [mail('Replay and offer', '$json.email', "'Thanks for joining ' + $json.event", "'Hi ' + $json.name + ', thank you for attending! Replay: ' + $('Config').first().json.replayUrl + '\\nAttendee offer (valid ' + $('Config').first().json.offerHours + ' hours): ' + $('Config').first().json.offerUrl"), row('Row: attended', "return [{json:{date:new Date().toISOString(),email:j.email,attended:'YES'}}];"), sheet_append('Log attended')],
   [mail('Replay only', '$json.email', "'Sorry we missed you at ' + $json.event", "'Hi ' + $json.name + ', here is the replay: ' + $('Config').first().json.replayUrl"), row('Row: no-show', "return [{json:{date:new Date().toISOString(),email:j.email,attended:'NO'}}];"), sheet_append('Log no-show')])],
 {'name': 'Pat', 'email': 'pat@x.com', 'attended': True, 'event': 'Automation 101'}, S, {}, ['Replay and offer', 'Log attended'], ['Replay only'])
